/**
 * Run the simulation from its current state for a single step.
 * The lifecycle is: snapshot state → act cycle → register newborns →
 * update stats → render → advance environment.
 */
public void simulateOneStep()
{
    step++;
    state.setCurrentStats(stats.getCounters());
    SimulationStepContext context = new SimulationStepContext(state);
    processAnimalCycle(context);
    registerNewborns(context);
    stats.update(field);
    view.showStatus(step, field, timeOfDay, state.getCurrentWeather(), stats.getSummary());
    state.setNormalisedTime(timeOfDay.normalisedTime());
    state.changeCurrentWeather();
}

/**
 * Give every simulatable its turn to act, then remove those that died.
 * Spawned offspring are collected into {@code context} for later merging.
 * @param context the step context that receives any newly spawned entities
 */
private void processAnimalCycle(SimulationStepContext context)
{
    for (Iterator<Simulatable> it = animals.iterator(); it.hasNext(); ) {
        Simulatable animal = it.next();
        animal.act(context);
        if (!animal.isAlive()) {
            it.remove();
        }
    }
}

/**
 * Merge all entities spawned during {@link #processAnimalCycle} into the
 * main population so they participate from the next step onward.
 * @param context the step context that holds the spawned entities
 */
private void registerNewborns(SimulationStepContext context)
{
    animals.addAll(context.getSpawned());
}

